import { useState } from 'react';
import { JxButton, JxInputField, JxStepper } from '@jinx-ui/react';

type SignupValues = {
  name: string;
  email: string;
  phone: string;
  city: string;
  street: string;
  zip: string;
};

type SignupWizardProps = {
  onSubmit: (values: SignupValues) => void;
};

const steps = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

const emptyValues: SignupValues = {
  name: '',
  email: '',
  phone: '',
  city: '',
  street: '',
  zip: '',
};

const summaryLabels: Array<[keyof SignupValues, string]> = [
  ['name', 'Имя'],
  ['email', 'Электронная почта'],
  ['phone', 'Телефон'],
  ['city', 'Город'],
  ['street', 'Улица и дом'],
  ['zip', 'Индекс'],
];

export default function SignupWizard({ onSubmit }: SignupWizardProps) {
  const [step, setStep] = useState(0);
  const [values, setValues] = useState<SignupValues>(emptyValues);

  const isLastStep = step === steps.length - 1;

  const setField =
    (field: keyof SignupValues) => (event: React.ChangeEvent<HTMLInputElement>) => {
      const next = event.target.value;
      setValues((current) => ({ ...current, [field]: next }));
    };

  const goBack = () => setStep((current) => Math.max(current - 1, 0));

  const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (isLastStep) {
      onSubmit(values);
      return;
    }
    setStep((current) => Math.min(current + 1, steps.length - 1));
  };

  return (
    <form
      onSubmit={handleSubmit}
      style={{ display: 'flex', flexDirection: 'column', gap: '24px' }}
    >
      <JxStepper steps={steps} current={step} />

      {step === 0 && (
        <div style={{ display: 'grid', gap: '16px' }}>
          <JxInputField
            label="Имя"
            required
            value={values.name}
            onChange={setField('name')}
            placeholder="Как к вам обращаться"
          />
          <JxInputField
            label="Электронная почта"
            type="email"
            required
            value={values.email}
            onChange={setField('email')}
            helperText="На неё придёт письмо с подтверждением"
          />
          <JxInputField
            label="Телефон"
            type="tel"
            prefix="+7"
            value={values.phone}
            onChange={setField('phone')}
          />
        </div>
      )}

      {step === 1 && (
        <div style={{ display: 'grid', gap: '16px' }}>
          <JxInputField
            label="Город"
            required
            value={values.city}
            onChange={setField('city')}
          />
          <JxInputField
            label="Улица и дом"
            required
            value={values.street}
            onChange={setField('street')}
          />
          <JxInputField
            label="Индекс"
            inputMode="numeric"
            value={values.zip}
            onChange={setField('zip')}
            helperText="Шесть цифр"
          />
        </div>
      )}

      {step === 2 && (
        <dl style={{ display: 'grid', gap: '12px', margin: 0 }}>
          {summaryLabels.map(([field, label]) => (
            <div key={field} style={{ display: 'grid', gap: '2px' }}>
              <dt
                style={{
                  color: 'var(--jx-text-2)',
                  fontFamily: 'var(--jx-font-sans)',
                  fontSize: '13px',
                }}
              >
                {label}
              </dt>
              <dd
                style={{
                  margin: 0,
                  color: values[field] ? 'var(--jx-text)' : 'var(--jx-text-3)',
                  fontFamily: 'var(--jx-font-sans)',
                }}
              >
                {values[field] || 'Не указано'}
              </dd>
            </div>
          ))}
        </dl>
      )}

      <div style={{ display: 'flex', gap: '8px', justifyContent: 'flex-end' }}>
        <JxButton variant="ghost" type="button" disabled={step === 0} onClick={goBack}>
          Назад
        </JxButton>
        <JxButton variant="primary" type="submit">
          {isLastStep ? 'Отправить' : 'Дальше'}
        </JxButton>
      </div>
    </form>
  );
}

